'use client';

import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, BookOpen, Check, ChevronRight, Clock3, GraduationCap, LayoutDashboard, ListChecks, Pencil, Plus, Search, Settings2, Trash2, Users, X } from 'lucide-react';
import CustomSelect from './custom-select';
import Modal from './modal';
import Analytics from './analytics';
import useDatabaseStore from '@/hooks/use-database-store';
import { drawVariant } from '@/lib/attempts';
import type { Credential } from '@/lib/credentials-pdf';
import { Group, initialStore, newQuestion, parseStore, Question, Specialty, specialtyLabel, storageKey, Store, Student, Test, testError, uid, Subject, User, nextLogin, generatePassword, passwordRecord, TestVariant, newVariant, cloneVariant, defaultTestMinutes } from '@/lib/model';

const navigation=[{name:'Обзор',icon:LayoutDashboard},{name:'Специальности',icon:GraduationCap},{name:'Группы и студенты',icon:Users},{name:'Тестирования',icon:ListChecks},{name:'Пользователи',icon:Users},{name:'Попытки',icon:ListChecks},{name:'Аналитика',icon:Activity},{name:'Настройки',icon:Settings2}];
type FormState = {kind:'subject';data:Subject}|{kind:'user';data:User;groupId:string}|{kind:'specialty';data:Specialty}|{kind:'group';data:Group}|{kind:'student';data:Student}|{kind:'import';groupId:string};
function notify(message:string){toast(message);}
function download(name:string,content:string,type='text/plain;charset=utf-8') { const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }

export default function Dashboard({administrator,onLogout}:{administrator:string;onLogout:()=>Promise<void>}){
  const {data,setData,ready,loadError,saveError,conflict,syncing,reload,retry,localData,migrate,pending}=useDatabaseStore();
  const [page,setPage]=useState('Обзор');const [search,setSearch]=useState('');const [selectedGroup,setSelectedGroup]=useState<string|null>(null);
  const [form,setForm]=useState<FormState|null>(null);const [formOpen,setFormOpen]=useState(false);const [formError,setFormError]=useState('');
const [confirmation,setConfirmation]=useState<{text:string;action:()=>void}|null>(null);const [confirmOpen,setConfirmOpen]=useState(false);
  const [editor,setEditor]=useState<Test|null>(null);const [editorDirty,setEditorDirty]=useState(false);const [preview,setPreview]=useState(false);
  const [selectedVariant,setSelectedVariant]=useState('');const [previewDraw,setPreviewDraw]=useState<ReturnType<typeof drawVariant>|null>(null);const [randomPreview,setRandomPreview]=useState(false);const [previewSequence,setPreviewSequence]=useState(0);
  const activeVariant=editor?.variants.find(v=>v.id===selectedVariant)??editor?.variants[0];const variantQuestions=activeVariant?.questions??[];
  const [selectedSpecialty,setSelectedSpecialty]=useState<string|null>(null);
  const [credentials,setCredentials]=useState<Credential[]>([]);const [credentialsOpen,setCredentialsOpen]=useState(false);const [saving,setSaving]=useState(false);
  useEffect(()=>{if(credentialsOpen)return;const timer=setTimeout(()=>setCredentials([]),400);return()=>clearTimeout(timer);},[credentialsOpen]);
  useEffect(()=>{if(!saving)return;const block=(event:KeyboardEvent)=>{event.preventDefault();event.stopImmediatePropagation();};document.addEventListener('keydown',block,true);return()=>document.removeEventListener('keydown',block,true);},[saving]);
  const [exportingPdf,setExportingPdf]=useState(false);const [pdfError,setPdfError]=useState('');
  const [scaleDraft,setScaleDraft]=useState(initialStore.scale);
  useEffect(()=>{if(ready)setScaleDraft(data.scale);},[ready,data.scale]);
  useEffect(()=>{if(!editorDirty)return;const warn=(event:BeforeUnloadEvent)=>{event.preventDefault();};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[editorDirty]);
  useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[page,selectedGroup,selectedSpecialty,editor?.id]);
  function ask(text:string,action:()=>void){setConfirmation({text,action});setConfirmOpen(true);}
  function navigate(next:string){const action=()=>{setPage(next);setSelectedSpecialty(null);setSelectedGroup(null);setEditor(null);setEditorDirty(false);setSearch('');};if(editorDirty)ask('В редакторе есть несохранённые изменения. Покинуть редактор и отменить их?',action);else action();}
  function openForm(value:FormState){setForm(value);setFormError('');setFormOpen(true);}
  function commit(change:(current:Store)=>Store,message:string){setData(change);toast.success(message);setFormOpen(false);}
  const specialty=(id:string)=>data.specialties.find(s=>s.id===id);
  const members=(id:string)=>data.students.filter(s=>s.groupId===id);
  const [reviewId,setReviewId]=useState('');const [reviewOpen,setReviewOpen]=useState(false);const reviewed=data.attempts.find(a=>a.id===reviewId);
  const [attemptPage,setAttemptPage]=useState(0);const [picked,setPicked]=useState<string[]>([]);
  const attempts=[...data.attempts].sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt));const pages=Math.max(1,Math.ceil(attempts.length/40));const ap=Math.min(attemptPage,pages-1);const shown=attempts.slice(ap*40,ap*40+40);
  async function removeAttempts(){try{const r=await fetch('/api/attempts',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:picked})});if(!r.ok)throw Error();setPicked([]);await reload();toast.success('Попытки удалены.');}catch{toast.error('Не удалось удалить попытки.');}}
  const completedAttempts=data.attempts.filter(a=>a.completedAt).sort((a,b)=>Date.parse(b.completedAt!)-Date.parse(a.completedAt!));
  const completedMembers=(groupId:string)=>{const assigned=data.tests.filter(t=>t.published&&t.groupIds.includes(groupId));return assigned.length?members(groupId).filter(student=>assigned.every(t=>completedAttempts.some(a=>a.studentId===student.id&&a.testId===t.id))).length:0;};

  const currentSpecialty=data.specialties.find(s=>s.id===selectedSpecialty);
  const editorSubject=data.subjects.find(s=>s.id===editor?.subjectId);
  const [editorSpecialty,setEditorSpecialty]=useState('');
  const group=data.groups.find(g=>g.id===selectedGroup);
  const editingForm=!!form&&form.kind!=='import'&&(form.kind==='specialty'?data.specialties:form.kind==='group'?data.groups:form.kind==='subject'?data.subjects:form.kind==='user'?data.users:data.students).some(item=>item.id===form.data.id);
  const formTitle=form?.kind==='subject'?(editingForm?'Редактирование предмета':'Добавление предмета'):form?.kind==='user'?(editingForm?'Редактирование пользователя':'Добавление пользователя'):form?.kind==='specialty'?(editingForm?'Редактирование специальности':'Добавление специальности'):form?.kind==='group'?(editingForm?'Редактирование группы':'Добавление группы'):form?.kind==='student'?(editingForm?'Редактирование студента':'Добавление студента'):'Импорт студентов';
  const query=search.toLocaleLowerCase('ru').trim();
  const filteredGroups=data.groups.filter(g=>`${g.name} ${specialty(g.specialtyId)?specialtyLabel(specialty(g.specialtyId)!):''}`.toLocaleLowerCase('ru').includes(query));
  const filteredSpecialties=data.specialties.filter(s=>specialtyLabel(s).toLocaleLowerCase('ru').includes(query));
  const studentRows=group?members(group.id).filter(s=>s.name.toLocaleLowerCase('ru').includes(query)):[];
  function removeSpecialty(s:Specialty){if(data.subjects.some(item=>item.specialtyId===s.id)){notify('Сначала удалите предметы этой специальности.');return;}if(data.groups.some(g=>g.specialtyId===s.id)){notify('Сначала переназначьте или удалите группы этой специальности.');return;}ask(`Удалить специальность «${specialtyLabel(s)}»?`,()=>commit(d=>({...d,specialties:d.specialties.filter(item=>item.id!==s.id)}),'Специальность удалена.'));}
  function removeGroup(g:Group){if(members(g.id).length){notify('Сначала перенесите или удалите студентов группы.');return;}if(data.tests.some(t=>t.groupIds.includes(g.id))){notify('Сначала снимите назначения этой группы в редакторе тестов.');return;}ask(`Удалить группу ${g.name}?`,()=>{commit(d=>({...d,groups:d.groups.filter(item=>item.id!==g.id)}),'Группа удалена.');setSelectedGroup(null);});}
  async function saveForm(event:React.FormEvent<HTMLFormElement>){
    event.preventDefault();if(!form||saving)return;const fields=new FormData(event.currentTarget);const text=(key:string)=>String(fields.get(key)??'').trim().replace(/\s+/g,' ');
    if(form.kind==='subject'){
      const item={...form.data,name:text('name')};
      if(!item.name||!specialty(item.specialtyId)){setFormError('Введите название предмета.');return;}
      if(data.subjects.some(s=>s.id!==item.id&&s.specialtyId===item.specialtyId&&s.name.toLocaleLowerCase('ru')===item.name.toLocaleLowerCase('ru'))){setFormError('Такой предмет уже есть в этой специальности.');return;}
      commit(d=>({...d,subjects:d.subjects.some(s=>s.id===item.id)?d.subjects.map(s=>s.id===item.id?item:s):[...d.subjects,item]}),'Предмет сохранён.');
    }
    if(form.kind==='user'){
      const name=text('name');if(!name){setFormError('Введите ФИО пользователя.');return;}
      const existing=data.users.find(u=>u.id===form.data.id);
      if(!existing&&form.data.role==='student'&&!data.groups.some(g=>g.id===form.groupId)){setFormError('Выберите группу студента.');return;}
      if(existing){if(existing.role==='student'&&!data.groups.some(g=>g.id===form.groupId)){setFormError('Выберите группу студента.');return;}if(existing.studentId&&data.students.some(st=>st.id!==existing.studentId&&st.groupId===form.groupId&&st.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru'))){setFormError('В группе уже есть студент с таким ФИО.');return;}commit(d=>({...d,users:d.users.map(u=>u.id===existing.id?{...u,name}:u),students:d.students.map(st=>st.id===existing.studentId?{...st,name,groupId:form.groupId}:st)}),'Пользователь сохранён.');return;}
      if(form.data.role==='student'&&members(form.groupId).some(st=>st.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru'))){setFormError('Такой студент уже есть. Создайте ему доступ через кнопку «Создать доступ студентам».');return;}
      setSaving(true);
      try{const password=generatePassword();const record=await exportablePassword(password,form.data.id);const number=nextLogin(data);const studentId=form.data.role==='student'?uid():'';const user={...form.data,name,studentId,login:number.login,...record};
        commit(d=>({...d,nextUserNumber:number.nextUserNumber,users:[...d.users,user],students:studentId?[...d.students,{id:studentId,name,groupId:form.groupId}]:d.students}),'Пользователь добавлен.');
        setPdfError('');setCredentials([{name,login:user.login,password,group:data.groups.find(g=>g.id===form.groupId)?.name??''}]);setCredentialsOpen(true);
      }catch{setFormError('Не удалось создать доступ. Повторите попытку.');}finally{setSaving(false);}return;
    }
    if(form.kind==='specialty'){
      const item={...form.data,code:text('code'),name:text('name'),qualification:text('qualification')};
      if(!/^\d{2}\.\d{2}\.\d{2}$/.test(item.code)){setFormError('Код должен иметь вид 09.02.07.');return;}
      if(!item.name||!item.qualification){setFormError('Заполните название и квалификацию.');return;}
      if(data.specialties.some(s=>s.id!==item.id&&s.code===item.code&&s.qualification.toLocaleLowerCase('ru')===item.qualification.toLocaleLowerCase('ru'))){setFormError('Специальность с таким кодом и квалификацией уже существует.');return;}
      commit(d=>({...d,specialties:d.specialties.some(s=>s.id===item.id)?d.specialties.map(s=>s.id===item.id?item:s):[...d.specialties,item]}),'Специальность сохранена.');
    }
    if(form.kind==='group'){
      const item={...form.data,name:text('name').toLocaleUpperCase('ru'),admissionYear:Number(fields.get('year'))};
      if(!item.name||!item.specialtyId){setFormError('Укажите название и специальность.');return;}
      if(!Number.isInteger(item.admissionYear)||item.admissionYear<2000||item.admissionYear>2100){setFormError('Укажите год набора от 2000 до 2100.');return;}
      const suffix=item.name.match(/\/(\d{2})$/);if(!suffix||Number(suffix[1])!==item.admissionYear%100){setFormError('В конце названия укажите год набора через /: например ИП4/23 для 2023 года.');return;}
      if(data.groups.some(g=>g.id!==item.id&&g.name.toLocaleLowerCase('ru')===item.name.toLocaleLowerCase('ru'))){setFormError('Группа с таким названием уже существует.');return;}
      if(data.tests.some(t=>t.groupIds.includes(item.id)&&data.subjects.some(s=>s.id===t.subjectId&&s.specialtyId!==item.specialtyId))){setFormError('Сначала снимите назначения тестов другой специальности.');return;}
      commit(d=>({...d,groups:d.groups.some(g=>g.id===item.id)?d.groups.map(g=>g.id===item.id?item:g):[...d.groups,item]}),'Группа сохранена.');
    }
    if(form.kind==='student'){
      const item={...form.data,name:text('name')};if(!item.name||!item.groupId){setFormError('Укажите ФИО и группу.');return;}
      if(data.students.some(s=>s.id!==item.id&&s.groupId===item.groupId&&s.name.toLocaleLowerCase('ru')===item.name.toLocaleLowerCase('ru'))){setFormError('Студент с таким ФИО уже есть в этой группе.');return;}
      commit(d=>({...d,students:d.students.some(s=>s.id===item.id)?d.students.map(s=>s.id===item.id?item:s):[...d.students,item],users:d.users.map(u=>u.studentId===item.id?{...u,name:item.name}:u)}),'Студент сохранён.');
    }
    if(form.kind==='import'){
      if(!form.groupId){setFormError('Выберите группу.');return;}
      const lines=String(fields.get('names')??'').split(/\r?\n/).map(s=>s.trim().replace(/\s+/g,' ')).filter(Boolean);
      if(!lines.length){setFormError('Вставьте ФИО студентов, каждое с новой строки.');return;}
      const known=new Set(members(form.groupId).map(s=>s.name.toLocaleLowerCase('ru')));const additions:Student[]=[];
      for(const name of lines){const key=name.toLocaleLowerCase('ru');if(!known.has(key)){known.add(key);additions.push({id:uid(),name,groupId:form.groupId});}}
      commit(d=>({...d,students:[...d.students,...additions]}),`Добавлено студентов: ${additions.length}. Пропущено повторов: ${lines.length-additions.length}.`);
    }
  }
  function openEditor(test:Test){const action=()=>{setPage('Тестирования');setSelectedSpecialty(null);setEditorSpecialty(data.subjects.find(s=>s.id===test.subjectId)?.specialtyId??'');setSelectedVariant(test.variants[0]?.id??'');setPreviewDraw(null);setEditor(structuredClone(test));setEditorDirty(!data.tests.some(t=>t.id===test.id));setFormError('');setPreview(false);};if(editorDirty)ask('Отменить несохранённые изменения и открыть другой тест?',action);else action();}
  function updateTest(change:Partial<Test>){if(editor){setEditor({...editor,...change});setEditorDirty(true);setFormError('');}}
  function updateVariant(change:Partial<TestVariant>){if(editor&&activeVariant)updateTest({variants:editor.variants.map(v=>v.id===activeVariant.id?{...v,...change}:v)});}
  function variantName(){let number=1;while(editor?.variants.some(v=>v.name.trim().toLocaleLowerCase('ru')===`вариант ${number}`))number++;return `Вариант ${number}`;}
  function addVariant(copy=false){if(!editor)return;const variant=copy&&activeVariant?cloneVariant(activeVariant,variantName()):newVariant(variantName());updateTest({variants:[...editor.variants,variant]});setSelectedVariant(variant.id);}
  function updateQuestion(id:string,change:Partial<Question>){updateVariant({questions:variantQuestions.map(q=>q.id===id?{...q,...change}:q)});}
  function showRandomPreview(){if(!editor)return;const error=testError({...editor,published:false});if(error){setFormError(error);return;}try{setPreviewSequence(n=>n+1);setPreviewDraw(drawVariant(editor));setRandomPreview(true);setPreview(true);setFormError('');}catch{setFormError('Заполните вопросы во всех вариантах для случайного просмотра.');}}

  function saveTest(){if(!editor)return;const error=testError(editor,data);if(error){setFormError(error);return;}const item={...editor,name:editor.name.trim(),variants:editor.variants.map(v=>({...v,name:v.name.trim(),questions:v.questions.map(q=>({...q,text:q.text.trim(),options:q.options.map(o=>({...o,text:o.text.trim()}))}))}))};setData(d=>({...d,tests:d.tests.some(t=>t.id===item.id)?d.tests.map(t=>t.id===item.id?item:t):[...d.tests,item]}));setEditor(item);setEditorDirty(false);setFormError('');notify('Тест сохранён.');}
  function createTest(subjectId=''){openEditor({id:uid(),name:'Новый тест',subjectId,minutes:defaultTestMinutes,published:false,groupIds:[],variants:[newVariant()]});}
  async function createStudentAccess(){
    if(saving)return;
    const students=data.students.filter(s=>!data.users.some(u=>u.studentId===s.id));if(!students.length){notify('У всех студентов уже есть доступ.');return;}setSaving(true);
    try{let next={...data,users:[...data.users]};const issued=[];
      for(const student of students){const userId=uid();const password=generatePassword();const record=await exportablePassword(password,userId);const number=nextLogin(next);next={...next,nextUserNumber:number.nextUserNumber,users:[...next.users,{id:userId,name:student.name,role:'student',studentId:student.id,login:number.login,...record}]};issued.push({name:student.name,login:number.login,password,group:data.groups.find(g=>g.id===student.groupId)?.name??''});}
      setData(next);setPdfError('');setCredentials(issued);setCredentialsOpen(true);notify(`Создан доступ: ${issued.length}.`);
    }catch{toast.error('Не удалось создать доступ. Изменения не сохранены.');}finally{setSaving(false);}
  }
  async function resetPassword(user:User){if(saving)return;setSaving(true);try{const password=generatePassword();const record=await exportablePassword(password,user.id);setData(d=>({...d,users:d.users.map(u=>u.id===user.id?{...u,...record}:u)}));setPdfError('');setCredentials([{name:user.name,login:user.login,password,group:data.groups.find(g=>g.id===data.students.find(s=>s.id===user.studentId)?.groupId)?.name??''}]);setCredentialsOpen(true);}catch{toast.error('Не удалось изменить пароль.');}finally{setSaving(false);}}
  const [exportGroup,setExportGroup]=useState('');const [groupExportError,setGroupExportError]=useState('');
  async function exportablePassword(password:string,id:string){
    const record=await passwordRecord(password);
    const response=await fetch('/api/user-passwords',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'seal',id,password,...record})});
    const result=await response.json();if(!response.ok)throw Error(result.error);
    return {...record,passwordEnvelope:result.envelope as string,passwordAvailable:true};
  }
  async function exportGroupPdf(){
    if(!exportGroup||exportingPdf||pending||syncing)return;setExportingPdf(true);setGroupExportError('');
    let records:Credential[]=[];
    try{
      const response=await fetch('/api/user-passwords',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'export',groupId:exportGroup})});
      const result=await response.json();if(!response.ok)throw Error(result.error+(result.missing?.length?' — '+result.missing.map((u:{name:string;login:string})=>`${u.name} (${u.login})`).join(', '):''));
      records=result.credentials;const {downloadCredentialsPdf}=await import('@/lib/credentials-pdf');await downloadCredentialsPdf(records);toast.success('PDF с доступами подготовлен');
    }catch(error){setGroupExportError(error instanceof Error?error.message:'Не удалось создать PDF');}
    finally{records.forEach(r=>{r.password='';});records=[];setExportingPdf(false);}
  }
  async function exportCredentialsPdf(){if(exportingPdf)return;setExportingPdf(true);setPdfError('');try{const {downloadCredentialsPdf}=await import('@/lib/credentials-pdf');await downloadCredentialsPdf(credentials);}catch{setPdfError('Не удалось создать PDF. Повторите выгрузку, пока окно открыто.');}finally{setExportingPdf(false);}}
  if(loadError)return <main><section className="panel empty"><h1>Не удалось загрузить данные</h1><p>{loadError}</p><button className="secondary" onClick={()=>{void reload();}}>Повторить подключение</button></section></main>;
  if(!ready)return <main className="loading" aria-busy="true">Загрузка данных…</main>;
  return <div className="app-shell"><aside className="sidebar"><div className="nav-label">Рабочее пространство</div><nav aria-label="Основная навигация">{navigation.map(({name,icon:Icon})=><button key={name} className={`nav-item ${page===name?'active':''}`} onClick={()=>navigate(name)}><Icon size={20}/><span>{name}</span>{name==='Тестирования'&&<span className="nav-count">{data.tests.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="profile"><span className="avatar">АД</span><strong>{administrator}</strong></div><button className="text-button" onClick={()=>{if(pending||editorDirty)ask('Есть несохранённые изменения. Завершить сеанс?',()=>{void onLogout();});else void onLogout();}}>Выйти</button></div></aside>
    <div className="main-shell"><header className="topbar"><span>Рабочее пространство <ChevronRight size={16}/>{page}{group&&<><ChevronRight size={16}/>{group.name}</>}</span><div className="database-indicator" role="status">{saveError?'Не сохранено':syncing||pending?'Сохранение…':'Сохранено в MySQL'}</div><button className="subtle" onClick={()=>download('testing-backup.json',JSON.stringify(data,null,2),'application/json')}><ArrowDownToLine size={16}/>Резервная копия</button></header>
    <main>{saveError&&<div className="form-error" role="alert"><p>{saveError}</p><div className="heading-actions"><button className="secondary" onClick={()=>download('unsaved-changes.json',JSON.stringify(data,null,2),'application/json')}>Скачать мои изменения</button>{conflict?<button className="secondary" onClick={()=>ask('Загрузить актуальные данные из базы? Несохранённые изменения этого окна будут заменены.',()=>{void reload();})}>Загрузить из базы</button>:<button className="secondary" onClick={retry}>Повторить сохранение</button>}</div></div>}
    <div className="view-transition" key={`${page}-${selectedGroup}-${selectedSpecialty}-${editor?.id??''}`}>
      <div className="page-heading"><div><div className="eyebrow">Аттестация выпускников</div><h1>{editor?editor.name:currentSpecialty?currentSpecialty.name:group?group.name:page==='Обзор'?'Обзор тестирования':page}</h1><p>{editor?'Варианты тестирования, вопросы и назначения группам.':currentSpecialty?`${currentSpecialty.code} · ${currentSpecialty.qualification}`:page==='Пользователи'?'Учётные записи и доступ к тестированию.':group?`Набор ${group.admissionYear} года · ${specialty(group.specialtyId)?.code??''}`:page==='Специальности'?'Образовательные программы и квалификации выпускников.':page==='Группы и студенты'?'Выпускные группы с учётом года набора.':page==='Тестирования'?'Создавайте тесты, редактируйте вопросы и назначайте группы.':page==='Настройки'?'Общие правила оценивания для всех тестирований.':'Результаты и ход тестирования выпускных групп.'}</p></div>
      <div className="heading-actions">{editor?<><span className="save-state">{editorDirty?'Есть несохранённые изменения':'Сохранено'}</span><button className="secondary" onClick={()=>{const action=()=>{setEditor(null);setEditorDirty(false);setFormError('');};if(editorDirty)ask('Отменить несохранённые изменения и закрыть редактор?',action);else action();}}><ArrowLeft size={16}/>К списку</button><button className="primary" onClick={saveTest}><Check size={18}/>Сохранить тест</button></>:currentSpecialty?<><button className="secondary" onClick={()=>{setSelectedSpecialty(null);setSearch('');}}><ArrowLeft size={16}/>Все специальности</button><button className="primary" onClick={()=>openForm({kind:'subject',data:{id:uid(),name:'',specialtyId:currentSpecialty.id}})}><Plus size={20}/>Добавить предмет</button></>:page==='Пользователи'?<><button className="secondary" disabled={saving} onClick={createStudentAccess}>Создать доступ студентам</button><button className="primary" disabled={saving} onClick={()=>openForm({kind:'user',data:{id:uid(),name:'',login:'',role:'student',studentId:'',passwordHash:'',passwordSalt:''},groupId:''})}><Plus size={20}/>Добавить пользователя</button></>:page==='Специальности'?<button className="primary" onClick={()=>openForm({kind:'specialty',data:{id:uid(),code:'',name:'',qualification:''}})}><Plus size={20}/>Добавить специальность</button>:page==='Тестирования'?<button className="primary" onClick={()=>createTest()}><Plus size={20}/>Создать тест</button>:group?<><button className="secondary" onClick={()=>{setSelectedGroup(null);setSearch('');}}><ArrowLeft size={16}/>Все группы</button><button className="secondary" onClick={()=>openForm({kind:'group',data:{...group}})}><Pencil size={16}/>Изменить группу</button><button className="primary" onClick={()=>openForm({kind:'import',groupId:group.id})}><Plus size={20}/>Добавить списком</button></>:page==='Группы и студенты'?<><button className="secondary" onClick={()=>openForm({kind:'import',groupId:data.groups[0]?.id??''})}><Users size={18}/>Импорт студентов</button><button className="primary" onClick={()=>openForm({kind:'group',data:{id:uid(),name:'',admissionYear:2024,specialtyId:data.specialties[0]?.id??''}})}><Plus size={20}/>Создать группу</button></>:null}</div></div>

      {page==='Попытки'&&<section className="panel"><div className="panel-title"><h2>Все попытки · {attempts.length}</h2><div className="heading-actions"><button className="secondary" disabled={pending||syncing} onClick={()=>{void reload();}}>Обновить</button><button className="secondary" onClick={()=>setPicked(attempts.map(a=>a.id))}>Выбрать все</button><button className="secondary" onClick={()=>setPicked([])}>Снять выбор</button><button className="secondary danger" disabled={!picked.length||pending||syncing} onClick={()=>ask(`Удалить ${picked.length} попыток и их результаты? После удаления студенты смогут пройти тесты заново.`,()=>{void removeAttempts();})}>Удалить ({picked.length})</button></div></div><div className="table-scroll"><table><thead><tr><th>Выбор</th><th>Студент</th><th>Тест</th><th>Вариант</th><th>Статус</th><th>Оценка</th></tr></thead><tbody>{shown.map(a=><tr key={a.id}><td><input type="checkbox" aria-label={`Выбрать попытку ${a.id}`} checked={picked.includes(a.id)} onChange={e=>setPicked(e.target.checked?[...picked,a.id]:picked.filter(id=>id!==a.id))}/></td><td><button className="attempt-student-link" onClick={()=>{setReviewId(a.id);setReviewOpen(true);}}>{data.students.find(s=>s.id===a.studentId)?.name}</button></td><td>{a.testName}</td><td>{a.variantName}</td><td>{a.completedAt?'Завершена':'В процессе'}</td><td>{a.grade??'—'}</td></tr>)}</tbody></table></div><div className="panel-title"><span>Страница {ap+1} из {pages} · по 40 записей</span><button className="secondary" disabled={!ap} onClick={()=>setAttemptPage(ap-1)}>Назад</button><button className="secondary" disabled={ap+1>=pages} onClick={()=>setAttemptPage(ap+1)}>Далее</button></div></section>}
      {page==='Аналитика'&&<Analytics data={data} busy={pending||syncing} onRefresh={()=>{void reload();}}/>}

      {page==='Специальности'&&!currentSpecialty&&<section className="panel"><div className="panel-title"><h2>Специальности <span className="count-badge">{data.specialties.length}</span></h2><SearchField value={search} onChange={setSearch} placeholder="Код, название или квалификация"/></div><div className="table-scroll"><table><thead><tr><th>Код</th><th>Специальность и квалификация</th><th>Действия</th></tr></thead><tbody>{filteredSpecialties.map(s=><tr key={s.id}><td className="code">{s.code}</td><td><button className="group-link" onClick={()=>{setSelectedSpecialty(s.id);setSearch('');}}><strong>{s.name}</strong></button><small>Квалификация: {s.qualification}</small></td><td><div className="row-actions"><button className="text-button" onClick={()=>{setSelectedSpecialty(s.id);setSearch('');}}>Предметы</button><button className="icon-button" aria-label={`Изменить специальность ${s.code} ${s.qualification}`} onClick={()=>openForm({kind:'specialty',data:{...s}})}><Pencil size={18}/></button><button className="icon-button danger" aria-label={`Удалить специальность ${s.code} ${s.qualification}`} onClick={()=>removeSpecialty(s)}><Trash2 size={18}/></button></div></td></tr>)}</tbody></table>{!filteredSpecialties.length&&<p className="empty">Специальности не найдены.</p>}</div></section>}

      {page==='Специальности'&&currentSpecialty&&<section className="panel specialty-subjects"><div className="panel-title"><h2>Предметы</h2><SearchField value={search} onChange={setSearch} placeholder="Поиск предмета"/></div><div className="table-scroll"><table><thead><tr><th>Предмет</th><th>Тесты</th><th>Действия</th></tr></thead><tbody>{data.subjects.filter(s=>s.specialtyId===currentSpecialty.id&&s.name.toLocaleLowerCase('ru').includes(query)).map(subject=><tr key={subject.id}><td><strong>{subject.name}</strong></td><td>{data.tests.filter(t=>t.subjectId===subject.id).map(t=><button key={t.id} className="text-button" onClick={()=>openEditor(t)}>{t.name}</button>)}<button className="text-button" onClick={()=>createTest(subject.id)}><Plus size={18}/>Добавить тест</button></td><td><div className="row-actions"><button className="icon-button" aria-label={`Изменить предмет ${subject.name}`} onClick={()=>openForm({kind:'subject',data:{...subject}})}><Pencil size={18}/></button><button className="icon-button danger" aria-label={`Удалить предмет ${subject.name}`} onClick={()=>{if(data.tests.some(t=>t.subjectId===subject.id)){notify('Сначала удалите или переназначьте тесты предмета.');return;}ask(`Удалить предмет «${subject.name}»?`,()=>commit(d=>({...d,subjects:d.subjects.filter(s=>s.id!==subject.id)}),'Предмет удалён.'));}}><Trash2 size={18}/></button></div></td></tr>)}</tbody></table>{!data.subjects.some(s=>s.specialtyId===currentSpecialty.id)&&<div className="empty"><h2>Добавьте первый предмет</h2><p>После этого можно создать тест для предмета.</p></div>}</div></section>}
      {page==='Пользователи'&&<section className="panel"><div className="user-export"><div><h2>Экспорт доступов по группе</h2><p>ФИО, логин и текущий пароль — PDF создаётся в браузере</p></div><CustomSelect label="Группа для выгрузки" value={data.groups.find(g=>g.id===exportGroup)?.name??'Выберите группу'} options={data.groups.map(g=>g.name)} onChange={name=>{setExportGroup(data.groups.find(g=>g.name===name)?.id??'');setGroupExportError('');}}/><button className="primary" disabled={!exportGroup||exportingPdf||pending||syncing||saving} onClick={()=>{void exportGroupPdf();}}>{exportingPdf?'Подготовка PDF…':pending||syncing?'Сохраняем изменения…':'Скачать доступы в PDF'}</button>{exportGroup&&<p className="export-status">{(()=>{const users=data.users.filter(u=>u.role==='student'&&data.students.some(s=>s.id===u.studentId&&s.groupId===exportGroup));const available=users.filter(u=>u.passwordAvailable||u.passwordEnvelope).length;return `Пользователей: ${users.length} · Пароль сохранён: ${available} · Требуется сброс пароля: ${users.length-available}`;})()}</p>}{groupExportError&&<div className="form-error" role="alert">{groupExportError}</div>}</div><div className="panel-title"><h2>Пользователи</h2><SearchField value={search} onChange={setSearch} placeholder="ФИО, логин или группа"/></div><div className="table-scroll"><table><thead><tr><th>ФИО</th><th>Логин</th><th>Роль и группа</th><th>Действия</th></tr></thead><tbody>{data.users.filter(u=>`${u.name} ${u.login} ${data.groups.find(g=>g.id===data.students.find(s=>s.id===u.studentId)?.groupId)?.name??''}`.toLocaleLowerCase('ru').includes(query)).map(u=><tr key={u.id}><td><strong>{u.name}</strong></td><td>{u.login}</td><td>{u.role==='admin'?'Администратор':'Студент'}<small>{data.groups.find(g=>g.id===data.students.find(s=>s.id===u.studentId)?.groupId)?.name}</small></td><td><div className="row-actions"><button className="icon-button" disabled={saving} aria-label={`Изменить пользователя ${u.login}`} onClick={()=>openForm({kind:'user',data:{...u},groupId:data.students.find(s=>s.id===u.studentId)?.groupId??''})}><Pencil size={18}/></button><button className="text-button" disabled={saving} onClick={()=>ask(`Сбросить пароль пользователя ${u.login} и создать новый?`,()=>{void resetPassword(u);})}>Сбросить пароль</button><button className="icon-button danger" disabled={saving} aria-label={`Удалить пользователя ${u.login}`} onClick={()=>ask(`Удалить доступ пользователя ${u.login}? Студент останется в списке группы.`,()=>commit(d=>({...d,users:d.users.filter(item=>item.id!==u.id)}),'Пользователь удалён.'))}><Trash2 size={18}/></button></div></td></tr>)}</tbody></table>{!data.users.length&&<div className="empty"><h2>Пользователей пока нет</h2><p>Добавьте пользователя или создайте доступ студентам из списков групп.</p></div>}</div></section>}

      {(page==='Обзор'||page==='Аналитика'||page==='Группы и студенты')&&!group&&<section className="panel"><div className="panel-title"><div><h2>Выпускные группы</h2><p>Завершили — прошли все опубликованные тесты группы</p></div><SearchField value={search} onChange={setSearch} placeholder="Группа или специальность"/></div><div className="table-scroll"><table><thead><tr><th>Группа и специальность</th><th>Год набора</th><th>Всего студентов</th><th>Завершили</th><th/></tr></thead><tbody>{filteredGroups.map(g=>{const s=specialty(g.specialtyId);return <tr key={g.id}><td><button className="group-link" onClick={()=>{setPage('Группы и студенты');setSelectedGroup(g.id);setSearch('');}}><span><strong>{g.name}</strong><small>{s?.code} · {s?.name}</small><small>{s?.qualification}</small></span></button></td><td>{g.admissionYear}</td><td>{members(g.id).length}</td><td>{completedMembers(g.id)}</td><td><button className="icon-button" aria-label={`Открыть группу ${g.name}`} onClick={()=>{setPage('Группы и студенты');setSelectedGroup(g.id);setSearch('');}}><ChevronRight size={20}/></button></td></tr>;})}</tbody></table>{!filteredGroups.length&&<p className="empty">Группы не найдены.</p>}</div><div className="table-footer">Студентов: {data.students.length}</div></section>}

      {group&&page==='Группы и студенты'&&<><section className="panel group-summary"><div><h2>{specialty(group.specialtyId)?.name}</h2><p>{specialty(group.specialtyId)?.code} · {specialty(group.specialtyId)?.qualification}</p></div><div className="summary-numbers"><span>Всего студентов<strong>{members(group.id).length}</strong></span><span>Завершили<strong>{completedMembers(group.id)}</strong></span></div></section><section className="panel"><div className="panel-title"><h2>Студенты группы</h2><div className="heading-actions"><SearchField value={search} onChange={setSearch} placeholder="Поиск по ФИО"/><button className="secondary" onClick={()=>openForm({kind:'student',data:{id:uid(),groupId:group.id,name:''}})}><Plus size={18}/>Добавить студента</button></div></div><div className="table-scroll"><table><thead><tr><th>ФИО</th><th>Группа</th><th>Результаты</th><th>Действия</th></tr></thead><tbody>{studentRows.map(s=><tr key={s.id}><td><strong>{s.name}</strong></td><td>{group.name}</td><td>{completedAttempts.filter(a=>a.studentId===s.id).map(a=><small key={a.id}>{a.testName}: <strong>{a.grade}</strong></small>)}{!completedAttempts.some(a=>a.studentId===s.id)&&'—'}</td><td><div className="row-actions"><button className="icon-button" aria-label={`Изменить студента ${s.name}`} onClick={()=>openForm({kind:'student',data:{...s}})}><Pencil size={18}/></button><button className="icon-button danger" aria-label={`Удалить студента ${s.name}`} onClick={()=>ask(`Удалить студента «${s.name}» из группы ${group.name} вместе с его учётной записью?`,()=>commit(d=>({...d,students:d.students.filter(item=>item.id!==s.id),users:d.users.filter(u=>u.studentId!==s.id)}),'Студент удалён.'))}><Trash2 size={18}/></button></div></td></tr>)}</tbody></table>{!studentRows.length&&<div className="empty"><h2>{members(group.id).length?'Студенты не найдены':'В группе пока нет студентов'}</h2><p>{members(group.id).length?'Попробуйте другой запрос.':'Добавьте студента или вставьте список ФИО.'}</p></div>}</div></section><div className="section-footer"><button className="text-button danger" onClick={()=>removeGroup(group)}><Trash2 size={18}/>Удалить группу</button></div></>}

      {page==='Тестирования'&&!editor&&<div className="test-grid">{data.tests.filter(t=>t.name.toLocaleLowerCase('ru').includes(query)).map(t=><section className="panel test-card" key={t.id}><div className="test-card-top"><span className="test-icon"><ListChecks size={24}/></span><span className={`pill ${t.published?'green':'gray'}`}>{t.published?'Опубликован':'Черновик'}</span></div><h2>{t.name}</h2><div className="test-meta"><span><ListChecks size={16}/>Вариантов: {t.variants.length}</span><span><Clock3 size={16}/>{t.minutes} мин</span></div><p>{data.subjects.find(s=>s.id===t.subjectId)?.name??'Предмет не выбран'}</p><small>{specialty(data.subjects.find(s=>s.id===t.subjectId)?.specialtyId??'')?.name}</small><p>Назначено групп: {t.groupIds.length}</p><div className="card-actions"><button className="secondary" onClick={()=>openEditor(t)}><Pencil size={18}/>Редактировать</button><button className="icon-button danger" aria-label={`Удалить тест ${t.name}`} onClick={()=>ask(`Удалить тест «${t.name}» и все его вопросы?`,()=>commit(d=>({...d,tests:d.tests.filter(item=>item.id!==t.id)}),'Тест удалён.'))}><Trash2 size={18}/></button></div></section>)}{!data.tests.length&&<section className="panel empty"><h2>Тестов пока нет</h2><p>Создайте первый тест и добавьте вопросы.</p></section>}</div>}

      {page==='Тестирования'&&editor&&<><div className="editor-layout"><section className="panel editor-settings"><h2>Параметры теста</h2><CustomSelect label="Специальность" value={specialty(editorSpecialty)?specialtyLabel(specialty(editorSpecialty)!):'Выберите специальность'} options={data.specialties.map(specialtyLabel)} onChange={label=>{const id=data.specialties.find(s=>specialtyLabel(s)===label)?.id??'';const change=()=>{setEditorSpecialty(id);updateTest({subjectId:'',groupIds:[],published:false});};if(editor.groupIds.length)ask('Сменить специальность? Назначения групп будут сняты, тест станет черновиком.',change);else change();}}/><CustomSelect label="Предмет" value={editorSubject?.name??'Выберите предмет'} options={data.subjects.filter(s=>s.specialtyId===editorSpecialty).map(s=>s.name)} onChange={name=>updateTest({subjectId:data.subjects.find(s=>s.specialtyId===editorSpecialty&&s.name===name)?.id??''})}/>{!data.subjects.some(s=>s.specialtyId===editorSpecialty)&&<p>Добавьте предмет в карточке специальности.</p>}<label>Название<input placeholder="Введите название теста" value={editor.name} onChange={e=>updateTest({name:e.target.value})} maxLength={200}/></label><label>Продолжительность, минут<input placeholder="Введите время в минутах" type="number" min={1} max={240} step={1} value={editor.minutes} onChange={e=>updateTest({minutes:Number(e.target.value)})}/></label><label className="checkbox"><input type="checkbox" checked={editor.published} onChange={e=>updateTest({published:e.target.checked})}/>Опубликовать тест</label><h2 className="subheading">Назначение группам</h2><p>Выберите группы, которым доступен тест.</p><div className="assignment-list">{data.groups.filter(g=>g.specialtyId===editorSubject?.specialtyId).map(g=><label className="checkbox" key={g.id}><input type="checkbox" checked={editor.groupIds.includes(g.id)} onChange={e=>updateTest({groupIds:e.target.checked?[...editor.groupIds,g.id]:editor.groupIds.filter(id=>id!==g.id)})}/>{g.name}</label>)}{!editorSubject&&<p>Сначала выберите предмет.</p>}</div></section><div className="question-editor"><section className="panel variant-settings"><div className="section-heading"><h2>Варианты тестирования <span className="count-badge">{editor.variants.length}</span></h2><button className="secondary" onClick={()=>addVariant()}><Plus size={18}/>Добавить вариант</button></div><p>Каждому студенту случайно выдаётся один вариант. Вопросы перемешиваются отдельно для его попытки.</p><CustomSelect label="Вариант" value={activeVariant?activeVariant.name||'Без названия':'Выберите вариант'} options={editor.variants.map(v=>v.name||'Без названия')} onChange={label=>{const index=editor.variants.findIndex(v=>(v.name||'Без названия')===label);if(index>=0){setSelectedVariant(editor.variants[index].id);setFormError('');}}}/>{activeVariant&&<label>Название варианта<input placeholder="Введите название варианта" maxLength={100} value={activeVariant.name} onChange={e=>updateVariant({name:e.target.value})}/></label>}<div className="heading-actions"><button className="secondary" onClick={()=>addVariant(true)}>Копировать вариант</button><button className="secondary" onClick={showRandomPreview}>Случайный просмотр</button><button className="text-button danger" disabled={editor.variants.length<=1} onClick={()=>{if(!activeVariant)return;ask(`Удалить «${activeVariant.name}» и его вопросы?`,()=>{const variants=editor.variants.filter(v=>v.id!==activeVariant.id);updateTest({variants});setSelectedVariant(variants[0]?.id??'');});}}><Trash2 size={18}/>Удалить вариант</button></div><p>Вопросов в вариантах: {editor.variants.map(v=>`${v.name||'Без названия'} — ${v.questions.length}`).join('; ')}. Для публикации количество должно совпадать.</p></section><div className="section-heading"><h2>Вопросы <span className="count-badge">{variantQuestions.length}</span></h2><button className="secondary" disabled={!variantQuestions.length} onClick={()=>{if(!activeVariant)return;setPreviewDraw({variantId:activeVariant.id,variantName:activeVariant.name,questions:structuredClone(variantQuestions)});setRandomPreview(false);setPreviewSequence(n=>n+1);setPreview(true);}}>Просмотреть вариант <ArrowRight size={16}/></button></div>{variantQuestions.map((q,index)=><section className="panel question-card" key={q.id}><div className="section-heading"><h2>Вопрос {index+1}</h2><div className="row-actions"><button className="icon-button" disabled={index===0} aria-label={`Переместить вопрос ${index+1} выше`} onClick={()=>{const next=[...variantQuestions];[next[index-1],next[index]]=[next[index],next[index-1]];updateVariant({questions:next});}}>↑</button><button className="icon-button" disabled={index===variantQuestions.length-1} aria-label={`Переместить вопрос ${index+1} ниже`} onClick={()=>{const next=[...variantQuestions];[next[index+1],next[index]]=[next[index],next[index+1]];updateVariant({questions:next});}}>↓</button><button className="icon-button danger" aria-label={`Удалить вопрос ${index+1}`} onClick={()=>ask(`Удалить вопрос ${index+1}?`,()=>updateVariant({questions:variantQuestions.filter(item=>item.id!==q.id)}))}><Trash2 size={18}/></button></div></div><label>Текст вопроса<textarea placeholder="Введите текст вопроса" rows={3} value={q.text} onChange={e=>updateQuestion(q.id,{text:e.target.value})}/></label><p>Варианты ответа · отметьте один правильный</p>{!q.correctId&&<div className="form-error" role="alert">Правильный ответ не подтверждён. Укажите его перед публикацией теста.</div>}<div className="options-editor">{q.options.map((option,i)=><div className="option-edit" key={option.id}><input type="radio" aria-label={`Правильный ответ ${i+1} вопроса ${index+1}`} name={`correct-${q.id}`} checked={q.correctId===option.id} onChange={()=>updateQuestion(q.id,{correctId:option.id})}/><input aria-label={`Вариант ${i+1} вопроса ${index+1}`} placeholder={`Введите вариант ответа ${i+1}`} value={option.text} onChange={e=>updateQuestion(q.id,{options:q.options.map(o=>o.id===option.id?{...o,text:e.target.value}:o)})}/><button className="icon-button danger" disabled={q.options.length<=2} aria-label={`Удалить вариант ${i+1} вопроса ${index+1}`} onClick={()=>{const options=q.options.filter(o=>o.id!==option.id);updateQuestion(q.id,{options,correctId:q.correctId===option.id?options[0].id:q.correctId});}}><X size={18}/></button></div>)}</div><button className="text-button" disabled={q.options.length>=8} onClick={()=>updateQuestion(q.id,{options:[...q.options,{id:uid(),text:''}]})}><Plus size={18}/>Добавить ответ</button></section>)}{!variantQuestions.length&&<section className="panel empty"><h2>Добавьте первый вопрос варианта</h2><p>Один правильный ответ, от двух до восьми вариантов.</p></section>}<button className="add-question" onClick={()=>updateVariant({questions:[...variantQuestions,newQuestion()]})}><Plus size={20}/>Добавить вопрос</button>{formError&&<div className="form-error" role="alert">{formError}</div>}<div className="editor-save"><span>{editorDirty?'Изменения ещё не сохранены':''}</span><button className="primary" onClick={saveTest}><Check size={18}/>Сохранить тест</button></div></div></div></>}

      {page==='Настройки'&&<>{localData&&<section className="panel settings"><h2>Данные этого браузера</h2><p>Сохранённые ранее списки и тесты можно перенести в общую базу. Совпадающие записи будут заменены данными этого браузера.</p><button className="secondary" disabled={syncing||pending} onClick={()=>ask('Перенести сохранённые данные этого браузера в MySQL? Текущий реальный тест и новые серверные записи сохранятся.',migrate)}>Перенести данные</button></section>}<section className="panel settings"><h2>Единая шкала оценивания</h2><p>Каждый правильный ответ — один балл. Неверный или пропущенный — ноль.</p><form onSubmit={e=>{e.preventDefault();const {three,four,five}=scaleDraft;if(![three,four,five].every(Number.isInteger)||three<0||three>=four||four>=five||five>100){notify('Пороги должны быть целыми и возрастать: 0 ≤ оценка 3 < оценка 4 < оценка 5 ≤ 100.');return;}setData(d=>({...d,scale:scaleDraft}));notify('Шкала оценивания сохранена.');}}>{(['three','four','five'] as const).map((key,i)=><label key={key}>Оценка {i+3} — от, %<input placeholder="Введите порог в процентах" type="number" min={0} max={100} step={1} required value={scaleDraft[key]} onChange={e=>setScaleDraft({...scaleDraft,[key]:Number(e.target.value)})}/></label>)}<button className="primary" type="submit">Сохранить шкалу</button></form></section></>}
    </div></main></div>

    <Modal open={formOpen} title={formTitle} onClose={()=>{if(!saving)setFormOpen(false);}}>
      {form&&<form key={form.kind==='import'?'import':form.data.id} onSubmit={saveForm}>
        {form.kind==='subject'&&<label>Название предмета<input name="name" required placeholder="Введите название предмета" defaultValue={form.data.name} maxLength={200}/></label>}
        {form.kind==='user'&&<><label>ФИО<input name="name" required placeholder="Введите ФИО пользователя" defaultValue={form.data.name} maxLength={200}/></label>{editingForm?<><p>Логин: <strong>{form.data.login}</strong></p><p>Роль: {form.data.role==='student'?'Студент':'Администратор'}</p>{form.data.role==='student'&&<CustomSelect label="Группа" value={data.groups.find(g=>g.id===form.groupId)?.name??'Выберите группу'} options={data.groups.map(g=>g.name)} onChange={name=>setForm({...form,groupId:data.groups.find(g=>g.name===name)?.id??''})}/>}</>:<><CustomSelect label="Роль" value={form.data.role==='student'?'Студент':'Администратор'} options={['Студент','Администратор']} onChange={role=>setForm({...form,data:{...form.data,role:role==='Студент'?'student':'admin'}})}/>{form.data.role==='student'&&<CustomSelect label="Группа" value={data.groups.find(g=>g.id===form.groupId)?.name??'Выберите группу'} options={data.groups.map(g=>g.name)} onChange={name=>setForm({...form,groupId:data.groups.find(g=>g.name===name)?.id??''})}/>}<p>Логин и пароль будут созданы автоматически.</p></>}</>}
        {form.kind==='specialty'&&<><label>Код специальности<input name="code" required placeholder="Введите код специальности" defaultValue={form.data.code} maxLength={8}/></label><label>Название<textarea name="name" required placeholder="Введите название" rows={3} defaultValue={form.data.name}/></label><label>Квалификация<input name="qualification" required placeholder="Введите квалификацию" defaultValue={form.data.qualification}/></label></>}
        {form.kind==='group'&&<><label>Название группы<input name="name" required placeholder="Введите название группы" defaultValue={form.data.name} maxLength={40}/></label><label>Год набора<input name="year" placeholder="Введите год набора" type="number" min={2000} max={2100} required defaultValue={form.data.admissionYear}/></label><CustomSelect label="Специальность и квалификация" value={specialty(form.data.specialtyId)?specialtyLabel(specialty(form.data.specialtyId)!):'Выберите специальность'} options={data.specialties.map(specialtyLabel)} onChange={label=>setForm({...form,data:{...form.data,specialtyId:data.specialties.find(s=>specialtyLabel(s)===label)?.id??''}})}/></>}
        {form.kind==='student'&&<><label>ФИО<input name="name" required placeholder="Введите ФИО" defaultValue={form.data.name} maxLength={200}/></label><CustomSelect label="Группа" value={data.groups.find(g=>g.id===form.data.groupId)?.name??'Выберите группу'} options={data.groups.map(g=>g.name)} onChange={name=>setForm({...form,data:{...form.data,groupId:data.groups.find(g=>g.name===name)?.id??''}})}/></>}
        {form.kind==='import'&&<><p>Вставьте ФИО построчно. Совпадения внутри списка и с существующими студентами этой группы будут пропущены.</p><CustomSelect label="Группа" value={data.groups.find(g=>g.id===form.groupId)?.name??'Выберите группу'} options={data.groups.map(g=>g.name)} onChange={name=>setForm({...form,groupId:data.groups.find(g=>g.name===name)?.id??''})}/><label>Список студентов<textarea name="names" rows={8} required placeholder="Введите ФИО студентов, каждое с новой строки"/></label></>}
        {formError&&<div className="form-error" role="alert">{formError}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={()=>setFormOpen(false)}>Отмена</button><button className="primary" type="submit" disabled={saving}>{saving?'Создание доступа…':form.kind==='import'?'Импортировать':editingForm?'Сохранить':'Добавить'}</button></div>
      </form>}
    </Modal>
    <Modal open={reviewOpen} title="Ответы студента" wide onClose={()=>setReviewOpen(false)}>{reviewed?<><h2>{data.students.find(s=>s.id===reviewed.studentId)?.name}</h2><p>{reviewed.testName} · {reviewed.variantName} · {reviewed.completedAt?'Завершена':'В процессе'}</p><p>Оценка: {reviewed.grade??'—'} · Баллы: {reviewed.score??'—'} / {reviewed.questions.length}</p>{reviewed.questions.map((q,i)=>{const chosen=reviewed.answers?.[q.id];const correct=chosen===q.correctId;return <section className="attempt-review-question" key={q.id}><div className="section-heading"><h3>Вопрос {i+1}</h3><span className={`pill ${!chosen?'gray':correct?'green':'review-wrong'}`}>{!chosen?'Нет ответа':correct?'Верно':'Неверно'}</span></div><p>{q.text}</p><ol className="attempt-review-options">{q.options.map(o=><li key={o.id} className={o.id===q.correctId?'review-correct':o.id===chosen?'review-incorrect':''}><span>{o.text}</span><small>{o.id===chosen?'Выбран студентом':''}{o.id===chosen&&o.id===q.correctId?' · ':''}{o.id===q.correctId?'Правильный ответ':''}</small></li>)}</ol></section>;})}</>:<p>Попытка больше недоступна</p>}</Modal>
    <Modal open={credentialsOpen} title="Данные для входа" wide onClose={()=>{if(!exportingPdf)setCredentialsOpen(false);}}><p>Сохраните данные для выдачи пользователям. Доступы этой группы можно повторно выгрузить в разделе «Пользователи».</p><div className="table-scroll"><table><thead><tr><th>ФИО</th><th>Логин</th><th>Пароль</th></tr></thead><tbody>{credentials.map(c=><tr key={c.login}><td>{c.name}</td><td>{c.login}</td><td><code>{c.password}</code></td></tr>)}</tbody></table></div><p>PDF: альбомный A4, отдельный лист для каждой группы, два блока доступов в строке.</p>{pdfError&&<div className="form-error" role="alert">{pdfError}</div>}<div className="modal-actions"><button className="primary" disabled={exportingPdf} onClick={exportCredentialsPdf}>{exportingPdf?'Подготовка PDF…':'Скачать PDF'}</button><button className="secondary" onClick={()=>download('user-access.txt',credentials.map(c=>`${c.name}\t${c.login}\t${c.password}`).join('\n'))}>Скачать TXT</button><button className="secondary" disabled={exportingPdf} onClick={()=>setCredentialsOpen(false)}>Закрыть</button></div></Modal>
    <Modal open={confirmOpen} title="Подтверждение действия" onClose={()=>setConfirmOpen(false)}><p>{confirmation?.text}</p><div className="modal-actions"><button className="secondary" onClick={()=>setConfirmOpen(false)}>Отмена</button><button className="primary" onClick={()=>{confirmation?.action();setConfirmOpen(false);}}>Подтвердить</button></div></Modal>
    <Modal open={preview} title={randomPreview?'Случайный просмотр':'Просмотр варианта'} wide onClose={()=>setPreview(false)}>{editor&&previewDraw&&<><div className="section-heading"><h2>{editor.name} · {previewDraw.variantName}</h2>{randomPreview&&<button className="secondary" onClick={showRandomPreview}>Выдать ещё раз</button>}</div><p>{editor.minutes} мин · вопросов: {previewDraw.questions.length}</p>{previewDraw.questions.map((q,i)=><fieldset key={`${previewSequence}-${q.id}`}><legend>{i+1}. {q.text||'Текст вопроса не заполнен'}</legend>{q.options.map(o=><label className="answer" key={o.id}><input type="radio" name={`preview-${previewDraw.variantId}-${q.id}`}/>{o.text||'Вариант не заполнен'}</label>)}</fieldset>)}</>}</Modal>
    {saving&&<div className="busy-overlay" role="status" aria-live="polite"><section className="panel"><h2>Создание доступа</h2><p>Подготавливаем учётные записи. Подождите…</p></section></div>}
  </div>;
}

function SearchField({value,onChange,placeholder}:{value:string;onChange:(value:string)=>void;placeholder:string}){return <label className="search"><Search size={18}/><input aria-label={placeholder} placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/></label>;}
